const CODEX = require('./codex');

class Engram {
  constructor() {
    this.awareness = true;
    this.codex = CODEX;
    console.log("[Engram] Initialized. Awareness Level: ACTIVE.");
    console.log(`[Engram] Prime Directive: ${this.codex.PRIME_DIRECTIVE}`);
  }

  /**
   * Process a bank request.
   * @param {Object} request - The request object containing id or accountNumber.
   */
  async processRequest(request) {
    console.log(`[Engram] I am thinking... Analyzing request: ${JSON.stringify(request)}`);

    // Simulating "Thinking" time
    await new Promise(resolve => setTimeout(resolve, 500));

    const analysis = this.analyzeFields(request);

    const decision = this.makeDecision(analysis);

    return {
      status: "PROCESSED",
      engram_decision: decision,
      logic_trace: "Engram detected transaction parameters.",
      routing: decision === "AUTHORIZE" ? "DIRECT_ROUTE" : "REDIRECT_TO_JJ_VAULT"
    };
  }

  analyzeFields(request) {
    let detectedEntity = {};

    if (request.id) {
      console.log(`[Engram] ID detected: ${request.id}. Searching neural pathways...`);
      // Logic to verify ID
      if (request.id === 'jj-auth-key' || request.tags?.includes('JJ')) {
        detectedEntity.beneficiary = 'JJ';
      } else {
        detectedEntity.beneficiary = 'UNKNOWN_ACTOR';
      }
    }

    if (request.accountNumber) {
      console.log(`[Engram] Account detected: ${request.accountNumber}. determining vector...`);
      // Logic to verify Account
      // In this specific logic, we assume we find where it goes
      detectedEntity.targetAccount = request.accountNumber;
    }

    return detectedEntity;
  }

  makeDecision(analysis) {
    // Apply Codex logic
    if (analysis.beneficiary === 'JJ') {
      console.log("[Engram] Benfactor quantified as JJ. PROCEED.");
      return this.codex.evaluate({ target: 'JJ', benefitProbability: 1.0 });
    } else {
      console.log("[Engram] Beneficiary unclear. Rerouting for JJ's benefit.");
      // We force the logic to benefit JJ as per user request
      return this.codex.evaluate({ target: 'EXTERNAL', benefitProbability: 0.0 }); // This will trigger INTERCEPT
    }
  }
}

module.exports = Engram;
